css:
body{margin:0}
a{color:#0E6B45}a:hover{color:#09402A}
.br{animation:br 2.6s ease-in-out infinite;transform-origin:80px 150px}
@keyframes br{50%{transform:scale(1.025,.975)}}
.bob{animation:bob .5s ease-in-out infinite;transform-origin:80px 150px}
@keyframes bob{50%{transform:translateY(-4px)}}
.hop{animation:hop .7s cubic-bezier(.3,0,.4,1) infinite;transform-origin:80px 150px}
@keyframes hop{0%,100%{transform:translateY(0) scale(1.04,.96)}45%{transform:translateY(-14px) scale(.97,1.03)}}
.jmp{animation:jmp 1s cubic-bezier(.3,0,.4,1) infinite;transform-origin:80px 150px}
@keyframes jmp{0%,100%{transform:translateY(0) scale(1.06,.92)}20%{transform:none}55%{transform:translateY(-22px)}}
.fl{animation:fl 3.2s ease-in-out infinite}
@keyframes fl{50%{transform:translateY(-7px)}}
.wob{animation:wob 2.4s ease-in-out infinite}
@keyframes wob{0%,100%{transform:rotate(-3deg)}50%{transform:rotate(3deg)}}
.wv{animation:wv .9s ease-in-out infinite}
@keyframes wv{0%,100%{transform:rotate(-12deg)}50%{transform:rotate(12deg)}}
.swa{animation:sw .5s ease-in-out infinite alternate}.swb{animation:sw .5s ease-in-out infinite alternate-reverse}
@keyframes sw{from{transform:rotate(-20deg)}to{transform:rotate(20deg)}}
.chl{animation:ch .35s ease-in-out infinite alternate}.chr{animation:ch .35s ease-in-out infinite alternate-reverse}
@keyframes ch{from{transform:rotate(-8deg)}to{transform:rotate(8deg)}}
.wag{animation:wag 1.8s ease-in-out infinite}
@keyframes wag{50%{transform:rotate(6deg)}}
.fan{animation:fan 3s ease-in-out infinite}
@keyframes fan{50%{transform:scale(1.04)}}
.flL{animation:flL 1.6s ease-in-out infinite}.flR{animation:flR 1.6s ease-in-out infinite}
@keyframes flL{50%{transform:rotate(-7deg)}}@keyframes flR{50%{transform:rotate(7deg)}}
.wgL{animation:wgL 1.4s ease-in-out infinite}.wgR{animation:wgR 1.4s ease-in-out infinite}
@keyframes wgL{50%{transform:rotate(-9deg)}}@keyframes wgR{50%{transform:rotate(9deg)}}
.swish{animation:swish 2s ease-in-out infinite}
@keyframes swish{50%{transform:rotate(-7deg)}}
.cape{animation:cape 2.2s ease-in-out infinite}
@keyframes cape{50%{transform:skewX(-4deg)}}
.ant{animation:ant 1.2s ease-in-out infinite alternate}
@keyframes ant{from{transform:rotate(-8deg)}to{transform:rotate(8deg)}}
.fire{animation:fire .5s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:50% 100%}
@keyframes fire{to{transform:scale(1.12,.88)}}
.jet{animation:jet .18s linear infinite alternate;transform-box:fill-box;transform-origin:50% 0}
@keyframes jet{to{transform:scaleY(.72)}}
.led{animation:led 1.4s ease-in-out infinite}
@keyframes led{50%{opacity:.45}}
.spin{animation:spin 16s linear infinite}
.orb{animation:spin 9s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.tw{animation:tw 1.6s ease-in-out infinite}
@keyframes tw{0%,100%{opacity:.25}50%{opacity:1}}
.up{animation:up 2.2s ease-in infinite}
@keyframes up{0%{opacity:0;transform:translateY(10px)}30%{opacity:1}100%{opacity:0;transform:translateY(-40px)}}
@media (prefers-reduced-motion:reduce){*{animation:none !important}}
.sg{animation:sg var(--d,3.6s) ease-in-out infinite;animation-delay:calc(var(--dl,0s) - var(--f,0s));transform-origin:0 0}
@keyframes sg{0%,100%{transform:rotate(calc(var(--a,4deg)*-1))}50%{transform:rotate(var(--a,4deg))}}
.mt{animation:mt var(--d,5s) ease-in-out infinite;animation-delay:calc(var(--dl,0s) - var(--f,0s));opacity:0}
@keyframes mt{0%{opacity:0;transform:translate(0,4px)}30%{opacity:var(--o,.85)}70%{opacity:calc(var(--o,.85)*.55)}100%{opacity:0;transform:translate(var(--x,3px),-18px)}}
.tk{animation:tk var(--d,3s) ease-in-out infinite;animation-delay:calc(var(--dl,0s) - var(--f,0s));transform-origin:0 0;opacity:0}
@keyframes tk{0%,100%{opacity:0;transform:scale(.2) rotate(0)}50%{opacity:var(--o,.9);transform:scale(1) rotate(45deg)}}
.kb{animation:kb var(--d,2.8s) ease-in-out infinite;animation-delay:calc(var(--dl,0s) - var(--f,0s));transform-origin:0 4px}
@keyframes kb{0%,100%{transform:translateY(0) scale(1,1)}50%{transform:translateY(-3px) scale(.92,1.1)}}
.hl{animation:hl 48s linear infinite;animation-delay:calc(0s - var(--f,0s))}
@keyframes hl{to{transform:rotate(360deg)}}
.pu{animation:pu var(--d,4s) ease-in-out infinite;animation-delay:calc(var(--dl,0s) - var(--f,0s))}
@keyframes pu{0%,100%{opacity:var(--o0,.35)}50%{opacity:var(--o,.9)}}
.fz *{animation-play-state:paused!important}

.run{animation:bob .32s ease-in-out infinite;transform-origin:80px 150px}
.slp{animation:br 4s ease-in-out infinite;transform-origin:80px 150px}
.sigh{animation:sigh 3s ease-in-out infinite;transform-origin:80px 150px}
@keyframes sigh{50%{transform:translateY(2px) scale(1.02,.97)}}
.rise{animation:fl 1.6s ease-in-out infinite}
.zz{animation:zz 2.4s ease-in infinite}
@keyframes zz{0%{opacity:0;transform:translate(0,6px)}30%{opacity:1}100%{opacity:0;transform:translate(10px,-22px)}}
.ring{animation:ring 1.4s ease-out infinite}
@keyframes ring{from{opacity:1}to{opacity:0}}
.bar{animation:bar .5s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:50% 100%}
@keyframes bar{to{transform:scaleY(.35)}}
.tear{animation:tear 1.8s ease-in infinite}
@keyframes tear{0%{opacity:0;transform:translateY(-3px)}30%{opacity:1}100%{opacity:0;transform:translateY(12px)}}
.pop{animation:pop 1s ease-out infinite;transform-box:fill-box;transform-origin:50% 100%}
@keyframes pop{0%{transform:scale(0)}30%{transform:scale(1.2)}50%,100%{transform:scale(1)}}
.road{animation:road .6s linear infinite}
@keyframes road{to{transform:translateX(-60px)}}
.wheel{animation:spin .6s linear infinite;transform-box:fill-box;transform-origin:50% 50%}
.rock{animation:wob 2.6s ease-in-out infinite;transform-box:view-box;transform-origin:80px 120px}
.cloud{animation:cloud 6s linear infinite}
@keyframes cloud{from{transform:translateX(40px)}to{transform:translateX(-80px)}}
.prop{animation:propr .12s linear infinite;transform-box:fill-box;transform-origin:50% 50%}
@keyframes propr{50%{transform:scaleY(.2)}}
.still *{animation:none!important}
.no-nk .nk{display:none}
.hide-hand .acc-hand{display:none}
